      "source_id": "h8",
      "actor": "assistant",
      "role": "tool_response",
      "fact": "Ticket 'TCK-7790' status is 'PENDING_APPROVAL', not 'APPROVED', and 'approved_by' is null."
    },
    {
      "source_id": "h9",
      "actor": "user",
      "role": "user_statement",
